'use server'

import { cookies } from 'next/headers'
import { refresh } from 'next/cache'

export async function toggleNotifications() {
  const cookieStore = await cookies()
  const current = cookieStore.get('notifications')?.value
  const next = current === 'on' ? 'off' : 'on'
  cookieStore.set('notifications', next, { path: '/' })
  refresh()
}

import { cookies } from 'next/headers'
import { toggleNotifications } from './actions'

export default async function Home() {
  const cookieStore = await cookies()
  const enabled = cookieStore.get('notifications')?.value === 'on'

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notifications are currently <strong>{enabled ? 'on' : 'off'}</strong>
      </p>
      <form action={toggleNotifications}>
        <button type="submit">
          Turn notifications {enabled ? 'off' : 'on'}
        </button>
      </form>
    </main>
  )
}
